import { memo, useCallback, useEffect, useLayoutEffect, useRef, useState, type UIEvent } from 'react'
import { dialogService } from '../../../services/dialog_service'
import type { ActionRunBindingStore } from '../run/state/action_run_binding_store'
import { ActionConversationChatlogTracker } from './action_conversation_chatlog_tracker'
import { ActionConversationEvolvingGroups } from './action_conversation_evolving_groups'
import { ActionConversationHistory } from './action_conversation_history'
import { ActionConversationQueuedPrompts } from './action_conversation_queued_prompts'
import { ActionConversationReservedBlocks } from './action_conversation_reserved_blocks'
import type { ActionConversationStore } from './action_conversation_store'

const CHAT_END_TOLERANCE = 4
const MIN_CHAT_HEIGHT = 96

interface ActionConversationTranscriptProps {
    bindingStore: ActionRunBindingStore
    store: ActionConversationStore
    trackerFactory?: (
        bindingStore: ActionRunBindingStore,
        store: ActionConversationStore,
    ) => ActionConversationChatlogTracker
}

function createChatlogTracker(bindingStore: ActionRunBindingStore, store: ActionConversationStore) {
    return new ActionConversationChatlogTracker(bindingStore, store)
}

function viewportIsAtEnd(viewport: HTMLDivElement) {
    return viewport.scrollHeight - viewport.clientHeight - viewport.scrollTop <= CHAT_END_TOLERANCE
}

/** Owns tracker lifecycle and renders subscribed transcript leaves. */
export const ActionConversationTranscript = memo(function ActionConversationTranscript(
    { bindingStore, store, trackerFactory = createChatlogTracker }: ActionConversationTranscriptProps,
) {
    const [tracker, setTracker] = useState<ActionConversationChatlogTracker | null>(null)
    const viewportRef = useRef<HTMLDivElement>(null)
    const viewportHeightRef = useRef<number | null>(null)
    const conversationIdentityRef = useRef<string | null>(null)
    const stuckToEndRef = useRef(true)

    const scrollToEnd = useCallback(() => {
        const viewport = viewportRef.current
        if (!viewport || !stuckToEndRef.current) return

        viewport.scrollTop = viewport.scrollHeight
    }, [])

    const handleScroll = (event: UIEvent<HTMLDivElement>) => {
        stuckToEndRef.current = viewportIsAtEnd(event.currentTarget)
    }

    const handleViewportResize = useCallback(() => {
        const viewport = viewportRef.current
        if (!viewport) return

        const previousViewportHeight = viewportHeightRef.current
        const viewportHeight = viewport.clientHeight
        viewportHeightRef.current = viewportHeight
        if (previousViewportHeight === viewportHeight) return

        scrollToEnd()
    }, [scrollToEnd])

    useEffect(() => {
        const nextTracker = trackerFactory(bindingStore, store)
        setTracker(null)
        try {
            nextTracker.load()
            setTracker(nextTracker)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not load conversation chatlog' })
        }

        return () => nextTracker.unload()
    }, [bindingStore, store, trackerFactory])

    useEffect(() => {
        if (!tracker) return undefined

        const handleContentChange = () => {
            scrollToEnd()
            queueMicrotask(scrollToEnd)
        }
        const handleConversationChange = () => {
            const conversationIdentity = tracker.getConversationIdentity()
            if (conversationIdentityRef.current !== conversationIdentity) stuckToEndRef.current = true
            conversationIdentityRef.current = conversationIdentity
            handleContentChange()
        }
        conversationIdentityRef.current = tracker.getConversationIdentity()
        const unsubscribers = [
            tracker.subscribeStableGroups(handleContentChange),
            tracker.subscribeEvolvingGroups(handleContentChange),
            tracker.subscribeReservedBlockCount(handleContentChange),
            tracker.subscribeQueuedPrompts(handleContentChange),
            tracker.subscribeConversation(handleConversationChange),
        ]

        return () => {
            for (const unsubscribe of unsubscribers) unsubscribe()
        }
    }, [scrollToEnd, tracker])

    useLayoutEffect(scrollToEnd, [scrollToEnd, tracker])

    useLayoutEffect(() => {
        const viewport = viewportRef.current
        if (!viewport) return

        viewportHeightRef.current = viewport.clientHeight
        const resizeObserver = new ResizeObserver(handleViewportResize)
        resizeObserver.observe(viewport)

        return resizeObserver.disconnect.bind(resizeObserver)
    }, [handleViewportResize])

    return (
        <Stack aria-label="Conversation chat" onScroll={handleScroll} ref={viewportRef} spacing={1}
            sx={{ flex: 1, minHeight: MIN_CHAT_HEIGHT, overflowX: 'hidden', overflowY: 'auto' }}>
            {tracker ? <ActionConversationHistory tracker={tracker} /> : null}
            {tracker ? <ActionConversationEvolvingGroups tracker={tracker} /> : null}
            {tracker ? <ActionConversationReservedBlocks tracker={tracker} /> : null}
            {tracker ? <ActionConversationQueuedPrompts tracker={tracker} /> : null}
        </Stack>
    )
})

import ExpandLessOutlined from '@mui/icons-material/ExpandLessOutlined'
import ExpandMoreOutlined from '@mui/icons-material/ExpandMoreOutlined'
import { Box, Button, Stack, Typography } from '@mui/material'
import { useState } from 'react'
import type { AgentConversationEvent } from '../../../data/data_types'
import { eventHasError, eventIdentity, eventStatusLabel } from './event_display'
import { reasoningDisplay } from './reasoning_display'

interface ReasoningEventProps {
    event: AgentConversationEvent
}

/** Subdued live reasoning summary preserving provider section boundaries. */
export function ReasoningEvent({ event }: ReasoningEventProps) {
    const completed = event.status === 'completed'
    const [expansion, setExpansion] = useState({ completed, expanded: !completed })
    if (expansion.completed !== completed) setExpansion({ completed, expanded: !completed })
    const expanded = !completed || expansion.expanded
    const { sections } = reasoningDisplay(event)
    const hasError = eventHasError(event.status)
    const toggleExpanded = () => {
        setExpansion((current) => ({ ...current, expanded: !current.expanded }))
    }

    return (
        <Box
            sx={{
                bgcolor: 'background.default',
                border: '1px solid',
                borderColor: hasError ? 'error.main' : 'divider',
                borderRadius: 1,
                flexShrink: 0,
                minWidth: 0,
                p: 1,
            }}
        >
            {completed ? (
                <Button
                    aria-expanded={expanded}
                    aria-label="Reasoning details"
                    endIcon={expanded ? <ExpandLessOutlined /> : <ExpandMoreOutlined />}
                    fullWidth
                    onClick={toggleExpanded}
                    sx={{ color: 'text.secondary', justifyContent: 'space-between', minWidth: 0, p: 0, textAlign: 'left' }}
                >
                    <Stack direction="row" spacing={1} sx={{ alignItems: 'center', minWidth: 0, width: '100%' }}>
                        <Typography sx={{ flex: 1, fontWeight: 600, minWidth: 0 }} variant="caption">Burning tokens</Typography>
                        <Typography color="custom.text3" role="status" variant="caption">
                            {eventStatusLabel(event.status)}
                        </Typography>
                    </Stack>
                </Button>
            ) : (
                <Stack direction="row" spacing={1} sx={{ alignItems: 'center', justifyContent: 'space-between' }}>
                    <Typography color="text.secondary" sx={{ fontWeight: 600 }} variant="caption">Burning tokens</Typography>
                    <Typography color={hasError ? 'error.main' : 'custom.text3'} role="status" variant="caption">
                        {eventStatusLabel(event.status)}
                    </Typography>
                </Stack>
            )}
            {expanded ? sections.map((section, index) => (
                <Typography
                    color={hasError ? 'error.main' : 'text.secondary'}
                    key={`${eventIdentity(event)}-section-${index}`}
                    sx={{ overflowWrap: 'anywhere', whiteSpace: 'pre-wrap' }}
                    variant="body2"
                >
                    {section}
                </Typography>
            )) : null}
        </Box>
    )
}

import TerminalOutlined from '@mui/icons-material/TerminalOutlined'
import { Box, Button, Stack, Typography } from '@mui/material'
import { useState } from 'react'
import type { AgentConversationEvent } from '../../../data/data_types'
import { commandPreview, eventHasError, eventStatusLabel } from './event_display'

const COMMAND_DETAIL_MAX_HEIGHT = 320

interface CommandExecutionEventProps {
    event: AgentConversationEvent
    grouped: boolean
}

function detailValue(value: string | number) {
    return (
        <Box
            component="pre"
            sx={{
                fontFamily: 'monospace',
                m: 0,
                overflowWrap: 'anywhere',
                whiteSpace: 'pre-wrap',
                wordBreak: 'break-word',
            }}
        >
            {value}
        </Box>
    )
}

/** Collapsed command lifecycle entry with exact execution detail on demand. */
export function CommandExecutionEvent({ event, grouped }: CommandExecutionEventProps) {
    const [expanded, setExpanded] = useState(false)
    const preview = commandPreview(event.command) || 'Command'
    const hasError = eventHasError(event.status)
    const durationMs = typeof event.durationMs === 'number' && Number.isFinite(event.durationMs)
        ? event.durationMs
        : null
    const exitCode = typeof event.exitCode === 'number' && Number.isSafeInteger(event.exitCode)
        ? event.exitCode
        : null
    const toggleExpanded = () => {
        setExpanded((current) => !current)
    }

    return (
        <Box
            sx={{
                border: grouped ? 'none' : '1px solid',
                borderColor: hasError ? 'error.main' : 'divider',
                borderRadius: grouped ? 0 : 1,
                flexShrink: 0,
                minWidth: 0,
                overflow: 'hidden',
            }}
        >
            <Button
                aria-expanded={expanded}
                aria-label={`Command details: ${preview}`}
                fullWidth
                onClick={toggleExpanded}
                startIcon={<TerminalOutlined />}
                sx={{
                    color: hasError ? 'error.main' : 'text.secondary',
                    display: 'flex',
                    justifyContent: 'flex-start',
                    minWidth: 0,
                    px: 1,
                    py: 0.75,
                    textAlign: 'left',
                }}
            >
                <Stack direction="row" spacing={1} sx={{ alignItems: 'center', minWidth: 0, width: '100%' }}>
                    <Typography noWrap sx={{ flex: 1, minWidth: 0 }} variant="caption">{preview}</Typography>
                    <Typography color="inherit" role="status" variant="caption">
                        {eventStatusLabel(event.status)}
                    </Typography>
                </Stack>
            </Button>
            {expanded ? (
                <Stack
                    spacing={1}
                    sx={{
                        bgcolor: 'background.default',
                        borderTop: '1px solid',
                        borderColor: 'divider',
                        color: hasError ? 'error.main' : 'text.secondary',
                        maxHeight: COMMAND_DETAIL_MAX_HEIGHT,
                        minWidth: 0,
                        overflow: 'auto',
                        p: 1,
                    }}
                >
                    <Box><Typography color="custom.text3" variant="caption">Command</Typography>{detailValue(event.command ?? '')}</Box>
                    {event.workingDirectory ? (
                        <Box><Typography color="custom.text3" variant="caption">Working directory</Typography>{detailValue(event.workingDirectory)}</Box>
                    ) : null}
                    {event.content ? (
                        <Box><Typography color="custom.text3" variant="caption">Output</Typography>{detailValue(event.content)}</Box>
                    ) : null}
                    {exitCode !== null || durationMs !== null ? (
                        <Stack direction="row" spacing={2}>
                            {exitCode !== null ? (
                                <Typography variant="caption">Exit code: {exitCode}</Typography>
                            ) : null}
                            {durationMs !== null ? (
                                <Typography variant="caption">Duration: {durationMs} ms</Typography>
                            ) : null}
                        </Stack>
                    ) : null}
                </Stack>
            ) : null}
        </Box>
    )
}

import BuildOutlined from '@mui/icons-material/BuildOutlined'
import { Box, Button, Stack, Typography } from '@mui/material'
import { useState } from 'react'
import type { AgentConversationEvent } from '../../../data/data_types'
import { eventHasError, eventStatusLabel, readableEventText } from './event_display'

const TOOL_DETAIL_MAX_HEIGHT = 240

interface AgentToolEventProps {
    event: AgentConversationEvent
    grouped: boolean
}

/** Generic compact renderer for normalized Codex tool and system events. */
export function AgentToolEvent({ event, grouped }: AgentToolEventProps) {
    const [expanded, setExpanded] = useState(false)
    const label = event.label ?? 'Agent event'
    const hasError = eventHasError(event.status)
    const contentLines = readableEventText(event.content)
    const outputLines = readableEventText(event.output)
    const durationMs = typeof event.durationMs === 'number' && Number.isFinite(event.durationMs)
        ? event.durationMs
        : null
    const hasDetail = contentLines.length > 0 || outputLines.length > 0 || durationMs !== null
    const toggleExpanded = () => {
        setExpanded((current) => !current)
    }

    return (
        <Box
            sx={{
                border: grouped ? 'none' : '1px solid',
                borderColor: hasError ? 'error.main' : 'divider',
                borderRadius: grouped ? 0 : 1,
                flexShrink: 0,
                minWidth: 0,
                overflow: 'hidden',
            }}
        >
            <Button
                aria-expanded={hasDetail ? expanded : undefined}
                aria-label={`${label} details`}
                disabled={!hasDetail}
                fullWidth
                onClick={toggleExpanded}
                startIcon={<BuildOutlined />}
                sx={{
                    color: hasError ? 'error.main' : 'text.secondary',
                    display: 'flex',
                    justifyContent: 'flex-start',
                    minWidth: 0,
                    px: 1,
                    py: 0.75,
                    textAlign: 'left',
                }}
            >
                <Stack direction="row" spacing={1} sx={{ alignItems: 'center', minWidth: 0, width: '100%' }}>
                    <Typography noWrap sx={{ flex: 1, minWidth: 0 }} variant="caption">{label}</Typography>
                    <Typography color="inherit" role="status" variant="caption">
                        {eventStatusLabel(event.status)}
                    </Typography>
                </Stack>
            </Button>
            {expanded ? (
                <Stack
                    spacing={1}
                    sx={{
                        bgcolor: 'background.default',
                        borderTop: '1px solid',
                        borderColor: 'divider',
                        color: hasError ? 'error.main' : 'text.secondary',
                        maxHeight: TOOL_DETAIL_MAX_HEIGHT,
                        minWidth: 0,
                        overflow: 'auto',
                        p: 1,
                    }}
                >
                    {contentLines.map((line, index) => (
                        <Typography key={`content-${index}`} sx={{ overflowWrap: 'anywhere', whiteSpace: 'pre-wrap' }} variant="body2">
                            {line}
                        </Typography>
                    ))}
                    {outputLines.map((line, index) => (
                        <Typography key={`output-${index}`} sx={{ overflowWrap: 'anywhere', whiteSpace: 'pre-wrap' }} variant="body2">
                            {line}
                        </Typography>
                    ))}
                    {durationMs !== null ? (
                        <Typography variant="caption">Duration: {durationMs} ms</Typography>
                    ) : null}
                </Stack>
            ) : null}
        </Box>
    )
}

import { Stack } from '@mui/material'
import { useEffect, useMemo, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../data/action_context'
import { agentAcknowledgementService } from '../../../services/agents/agent_acknowledgement_service'
import { cardPopupService, subscribeCardPopups } from '../../../services/card_popup_service'
import { useBoundRunId, useRunSelector } from '../../hooks/use_action_runs'
import {
    ActionConversationTranscript,
} from './action_conversation_transcript'
import {
    createAcknowledgementConversationSelector,
} from './action_conversation_chat_selectors'
import { resolveDisplayedConversation, type ActionConversationStore } from './action_conversation_store'
import { ConversationMetaInfo } from './conversation_meta_info'
import type { ActionRunBindingStore } from '../run/state/action_run_binding_store'
import type { ActionUsageValuesService } from '../run/popup/action_usage_values_service'

interface ActionConversationChatProps {
    actionId: string
    bindingStore: ActionRunBindingStore
    context: ActionContext
    popupEntryId?: string
    store: ActionConversationStore
    usageValuesService?: ActionUsageValuesService
}

/** Conversation surface; owns selection, live-run, visibility, and acknowledgement subscriptions. */
export function ActionConversationChat(
    { actionId, bindingStore, context, popupEntryId, store, usageValuesService }: ActionConversationChatProps,
) {
    const selectAcknowledgementConversation = useMemo(() => createAcknowledgementConversationSelector(), [])
    const boundRunId = useBoundRunId(bindingStore)
    const liveConversation = useRunSelector(boundRunId, selectAcknowledgementConversation)
    const { selectedConversation } = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const popupEntries = useSyncExternalStore(
        subscribeCardPopups,
        () => cardPopupService.getSnapshot(),
        () => cardPopupService.getSnapshot(),
    )
    const conversation = resolveDisplayedConversation(liveConversation, selectedConversation)
    const scope = context.cardInternalId ?? null
    const popupVisible = context.kind === 'project' || popupEntries.at(-1)?.id === popupEntryId
    const visible = !!popupEntryId && popupVisible && !!conversation

    useEffect(() => {
        if (!popupEntryId || !conversation) return undefined

        agentAcknowledgementService.setConversationVisible(popupEntryId, scope, actionId, conversation, visible)

        return () => agentAcknowledgementService.setConversationVisible(
            popupEntryId, scope, actionId, conversation, false,
        )
    }, [actionId, conversation, popupEntryId, scope, visible])

    return (
        <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>
            <ActionConversationTranscript
                bindingStore={bindingStore}
                store={store}
            />
            <ConversationMetaInfo bindingStore={bindingStore} store={store} usageValuesService={usageValuesService} />
        </Stack>
    )
}

import type { AgentConversationEvent } from '../../../data/data_types'

const COMMAND_PREVIEW_LENGTH = 96

export function eventStatusLabel(status?: string) {
    if (!status) return 'Unknown'
    if (status === 'inProgress' || status === 'running' || status === 'started') return 'Running'
    if (status === 'completed') return 'Completed'
    if (status === 'failed') return 'Failed'
    if (status === 'declined') return 'Declined'

    return status
}

export function eventHasError(status?: string) {
    return status === 'failed' || status === 'declined'
}

export function commandPreview(command?: string) {
    const oneLine = command?.replace(/\s+/gu, ' ').trim() ?? ''
    const characters = Array.from(oneLine)
    if (characters.length <= COMMAND_PREVIEW_LENGTH) return oneLine

    return `${characters.slice(0, COMMAND_PREVIEW_LENGTH - 1).join('')}â€¦`
}

export function readableEventText(value?: string) {
    return value?.trim() ? value.split(/\r?\n/u) : []
}

export function eventIdentity(event: AgentConversationEvent) {
    return event.providerItemId ?? event.id
}

