import { Box } from '@mui/material'
import { memo } from 'react'
import type { AgentConversationEventEntry } from '../../../data/data_types'
import { AgentToolEvent } from './agent_tool_event'
import { CommandExecutionEvent } from './command_execution_event'
import { ReasoningEvent } from './reasoning_event'

interface ActionConversationEventRowProps {
    entry: AgentConversationEventEntry
    grouped: boolean
}

/** Renders one referentially stable transcript event. */
export const ActionConversationEventRow = memo(function ActionConversationEventRow({ entry, grouped }: ActionConversationEventRowProps) {
    if (entry.type === 'reasoning') return <Box sx={{ minWidth: 0 }}><ReasoningEvent event={entry} /></Box>
    if (entry.type === 'commandExecution') {
        return <Box sx={{ minWidth: 0 }}><CommandExecutionEvent event={entry} grouped={grouped} /></Box>
    }

    return <Box sx={{ minWidth: 0 }}><AgentToolEvent event={entry} grouped={grouped} /></Box>
})

import { memo, useSyncExternalStore } from 'react'
import type { ActionConversationChatlogTracker } from './action_conversation_chatlog_tracker'
import { ActionConversationGroupList } from './action_conversation_group_list'

interface ActionConversationHistoryProps {
    tracker: ActionConversationChatlogTracker
}

/** Subscribes to and renders low-change conversation groups. */
export const ActionConversationHistory = memo(function ActionConversationHistory(
    { tracker }: ActionConversationHistoryProps,
) {
    const groups = useSyncExternalStore(
        tracker.subscribeStableGroups,
        tracker.getStableGroups,
        tracker.getStableGroups,
    )

    return <ActionConversationGroupList cardInternalId={tracker.getCardInternalId()} groups={groups} tracker={tracker} />
})

import type { ActionConversationRenderGroup } from './action_conversation_render_groups'
import type { ActionConversationChatlogTracker } from './action_conversation_chatlog_tracker'
import { ActionConversationEventRow } from './action_conversation_event_row'
import { ActionConversationMessage } from './action_conversation_message'
import { SubAgentGroup } from './sub_agent_group'
import { TerminalToolCallGroup } from './terminal_tool_call_group'

interface ActionConversationGroupListProps {
    cardInternalId: string | null
    groups: ActionConversationRenderGroup[]
    tracker: ActionConversationChatlogTracker
}

/** Maps stable conversation render groups to their leaf components. */
export function ActionConversationGroupList({ cardInternalId, groups, tracker }: ActionConversationGroupListProps) {
    return groups.map((group) => {
        if (group.kind === 'terminalToolCalls') {
            return (
                <TerminalToolCallGroup
                    entries={group.entries}
                    groupKey={group.key}
                    key={group.key}
                    tracker={tracker}
                />
            )
        }
        if (group.kind === 'subAgent') {
            return (
                <SubAgentGroup
                    entry={group.entry}
                    groupKey={group.key}
                    groups={group.groups}
                    key={group.key}
                    label={group.label}
                    tracker={tracker}
                    runningCount={group.runningCount}
                />
            )
        }

        const { entry } = group
        if (entry.kind === 'message') {
            return <ActionConversationMessage cardInternalId={cardInternalId} entry={entry} key={group.key} />
        }

        return <ActionConversationEventRow entry={entry} grouped={false} key={group.key} />
    })
}

