            >
                <Typography noWrap sx={{ minWidth: 0 }} variant="caption">
                    {label} ({groupEntryCount(groups)}){runningCount > 0 ? ` â€” ${runningCount} running` : ''}
                </Typography>
            </Button>
            {expanded ? groups.map((group) => {
                if (group.kind === 'terminalToolCalls') {
                    return (
                        <TerminalToolCallGroup
                            entries={group.entries}
                            groupKey={group.key}
                            key={group.key}
                            tracker={tracker}
                        />
                    )
                }
                if (group.kind === 'subAgent') {
                    return (
                        <SubAgentGroup
                            entry={group.entry}
                            groupKey={group.key}
                            groups={group.groups}
                            key={group.key}
                            label={group.label}
                            tracker={tracker}
                            runningCount={group.runningCount}
                        />
                    )
                }
                if (group.entry.kind !== 'event') return null

                return (
